import{_ as a,o as r,c as t,a4 as i}from"./chunks/framework.CzJ_HCFe.js";const p=JSON.parse('{"title":"General Purchase Source Profile","description":"","frontmatter":{},"headers":[],"relativePath":"reference/39-purchase-profile.md","filePath":"reference/39-purchase-profile.md","lastUpdated":1788532705000}'),n={name:"reference/39-purchase-profile.md"};function s(o,e,h,l,c,d){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="general-purchase-source-profile" tabindex="-1">General Purchase Source Profile <a class="header-anchor" href="#general-purchase-source-profile" aria-label="Permalink to &quot;General Purchase Source Profile&quot;">​</a></h1><h2 id="authority-and-scope" tabindex="-1">Authority and scope <a class="header-anchor" href="#authority-and-scope" aria-label="Permalink to &quot;Authority and scope&quot;">​</a></h2><p>The generic Purchase profile uses Rama Daivajna’s <em>Muhurta Chintamani</em>, Sanskrit text with Hindi commentary, Internet Archive identifier <code>muhurta-chintamani-hindi</code>:</p><ul><li>Nakshatra-prakarana, purchase/sale distinction and purchase Muhurta, verse 16, printed pages 33–34; OCR lines 2336–2350.</li><li>Marketplace election, verse 17, printed pages 34–35; OCR lines 2351–2374.</li></ul><p>The scan does not expose publisher or publication-date metadata. The stable verse, printed-page, repository-source and OCR locators make that limitation explicit rather than hiding it.</p><h2 id="automated-rule" tabindex="-1">Automated rule <a class="header-anchor" href="#automated-rule" aria-label="Permalink to &quot;Automated rule&quot;">​</a></h2><p>Verse 16 names six Nakshatras as favorable for purchase:</p><ul><li>Revati</li><li>Shatabhisha</li><li>Ashvini (source-facing configuration retains “Ashwini” and normalizes it)</li><li>Swati</li><li>Shravana</li><li>Chitra</li></ul><p>These stars receive the activity-specific source-backed bonus. The passage calls them favorable; it does not say that every other Nakshatra is forbidden, so the implementation uses a preference instead of a hard admission gate.</p><h2 id="role-and-marketplace-checks" tabindex="-1">Role and marketplace checks <a class="header-anchor" href="#role-and-marketplace-checks" aria-label="Permalink to &quot;Role and marketplace checks&quot;">​</a></h2><p>Verse 16 expressly distinguishes buying from selling. This profile is for the buyer; a seller election cannot silently inherit it.</p><p>Verse 17 adds marketplace-chart criteria: reject Rikta Tithis, Tuesday and Kumbha Lagna; prefer Chandra and Shukra in Lagna; keep malefics out of the 8th and 12th; place benefics in the 2nd, 10th or 11th.</p><p>The Drik browser post-screen now computes the two exact Chandra/Shukra-in-Lagna preferences only when they pass across every sampled state: the window edges and both sides of every known interior Drik Lagna transition. They are tie-break evidence only. The other marketplace clauses and buyer/seller scope remain manual; Python/MCP do not call the chart service. See <a href="./54-muhurtam-election-chart-screening">Muhurtam election-chart screening</a>.</p><h2 id="non-inherited-heuristics-and-narrower-profiles" tabindex="-1">Non-inherited heuristics and narrower profiles <a class="header-anchor" href="#non-inherited-heuristics-and-narrower-profiles" aria-label="Permalink to &quot;Non-inherited heuristics and narrower profiles&quot;">​</a></h2><p>The Labh-Choghadiya bonus is a transparent project-ranking heuristic. Verses 16–17 do not authorize it.</p><p>When the object is known, the dedicated vehicle, building-land or gold/jewelry profile is the narrower authority and takes precedence. A generic purchase citation must not flatten their distinct rules.</p>',16)])])}const f=a(n,[["render",s]]);export{p as __pageData,f as default};
